//! Copies the cell-width table generated by Nix into `OUT_DIR`.
//!
//! The table is `East_Asian_Width` plus `Emoji_Presentation`, taken from the
//! Unicode files by `nix/scripts/gen-width.py`. This build script does NOT
//! generate it — generating here would be a second opinion about Unicode, kept
//! in Rust, going stale one release at a time. Same shape as
//! `ronoctua-tokens/build.rs`.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_WIDTH_RS");

    let generated = env::var("RONOCTUA_WIDTH_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_WIDTH_RS is not set.\n\
             \n\
             The cell-width table is generated by Nix out of the Unicode\n\
             character database. Enter the environment with `direnv allow` (or\n\
             `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`.\n\
             \n\
             Generating it here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("width.rs");
    // DELETE FIRST — the store file is read-only and `fs::copy` inherits the
    // mode. See `ronoctua-tokens/build.rs`.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
